-- Upper bounds on every user-entered text column, enforced by the
-- database whatever the code path. Generous, well above real use; a
-- rejected save surfaces as the action's existing error message.
-- (Verified no existing row exceeds these before adding them.)
alter table public.messages add constraint messages_content_len check (char_length(content) <= 4000);
alter table public.complaints add constraint complaints_subject_len check (char_length(subject) <= 200);
alter table public.complaints add constraint complaints_description_len check (char_length(description) <= 5000);
alter table public.complaints add constraint complaints_resolution_note_len check (char_length(resolution_note) <= 5000);
alter table public.complaints add constraint complaints_submitted_by_name_len check (char_length(submitted_by_name) <= 200);
alter table public.homework add constraint homework_title_len check (char_length(title) <= 200);
alter table public.homework add constraint homework_description_len check (char_length(description) <= 5000);
alter table public.homework_submissions add constraint homework_submissions_text_answer_len check (char_length(text_answer) <= 10000);
alter table public.homework_grades add constraint homework_grades_feedback_len check (char_length(feedback) <= 3000);
alter table public.progress_reports add constraint progress_reports_notes_len check (char_length(notes) <= 5000);
alter table public.exams add constraint exams_title_len check (char_length(title) <= 200);
alter table public.exams add constraint exams_exam_type_len check (char_length(exam_type) <= 100);
alter table public.teaching_notes add constraint teaching_notes_title_len check (char_length(title) <= 200);
alter table public.halaqa_visit_reports add constraint halaqa_visit_reports_title_len check (char_length(title) <= 200);
alter table public.halaqa_visit_reports add constraint halaqa_visit_reports_notes_len check (char_length(notes) <= 5000);
alter table public.campaign_leads add constraint campaign_leads_name_len check (char_length(name) <= 200);
alter table public.campaign_leads add constraint campaign_leads_contact_len check (char_length(contact) <= 200);
alter table public.campaign_leads add constraint campaign_leads_notes_len check (char_length(notes) <= 2000);
alter table public.campaign_leads add constraint campaign_leads_source_len check (char_length(source) <= 100);
alter table public.finance_records add constraint finance_records_category_len check (char_length(category) <= 200);
alter table public.finance_records add constraint finance_records_description_len check (char_length(description) <= 1000);
alter table public.budgets add constraint budgets_category_len check (char_length(category) <= 200);
alter table public.salary_allocations add constraint salary_allocations_payee_len check (char_length(payee) <= 200);
alter table public.salary_allocations add constraint salary_allocations_category_len check (char_length(category) <= 200);
alter table public.classrooms add constraint classrooms_name_len check (char_length(name) <= 120);
alter table public.classrooms add constraint classrooms_meeting_link_len check (char_length(meeting_link) <= 500);
alter table public.profiles add constraint profiles_name_len check (char_length(name) <= 120);
alter table public.profiles add constraint profiles_address_len check (char_length(address) <= 500);
alter table public.profiles add constraint profiles_place_len check (char_length(place) <= 200);
alter table public.profiles add constraint profiles_phone_len check (char_length(phone) <= 32);
alter table public.profiles add constraint profiles_whatsapp_number_len check (char_length(whatsapp_number) <= 32);
alter table public.profiles add constraint profiles_username_len check (char_length(username) <= 40);
alter table public.profiles add constraint profiles_email_len check (char_length(email) <= 254);
alter table public.profiles add constraint profiles_rejection_reason_len check (char_length(rejection_reason) <= 1000);
